begin;
set local search_path=public,extensions;
select no_plan();
-- business dm fixtures
insert into public.conversations(id,kind,user_low_id,business_low_id,business_high_id,status) values
  ('b1950000-0000-4000-8000-000000000001','business','b1900000-0000-4000-8000-000000000003',null,'b1910000-0000-4000-8000-000000000001','active'),
  ('b1950000-0000-4000-8000-000000000002','business',null,'b1910000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000002','active');
insert into public.messages(id,conversation_id,sender_id,sender_business_id,body,created_at) values
  ('b1960000-0000-4000-8000-000000000001','b1950000-0000-4000-8000-000000000001','b1900000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001','Evidence before deletion',now()-interval '3 seconds'),
  ('b1960000-0000-4000-8000-000000000002','b1950000-0000-4000-8000-000000000001','b1900000-0000-4000-8000-000000000003',null,'Personal question',now()-interval '2 seconds'),
  ('b1960000-0000-4000-8000-000000000003','b1950000-0000-4000-8000-000000000002','b1900000-0000-4000-8000-000000000005','b1910000-0000-4000-8000-000000000002','Second business',now()-interval '1 second');
select throws_ok($$insert into public.messages(conversation_id,sender_id,body) values('b1950000-0000-4000-8000-000000000002','b1900000-0000-4000-8000-000000000001','Missing business identity')$$,'P0001','BUSINESS_ENDPOINT_MISMATCH','even privileged insert cannot turn missing business identity into a private actor DTO');
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_business_chat_messages('b1950000-0000-4000-8000-000000000002','b1910000-0000-4000-8000-000000000001')->'conversation'->'other_identity'->>'id','b1910000-0000-4000-8000-000000000002','business-to-business uses distinct business endpoints');
select is(public.start_business_conversation('b1910000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000002',null),'b1950000-0000-4000-8000-000000000002'::uuid,'business peer can start/reuse same immutable room');
select throws_ok($$select public.start_business_conversation('b1910000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001',null)$$,'P0001','INVALID_RECIPIENT','same public identity cannot chat with itself');
select throws_ok($$select public.send_business_chat_message('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001',gen_random_uuid(),p_body=>'Cross-room reply',p_reply_to_id=>'b1960000-0000-4000-8000-000000000003')$$,'P0001','MESSAGE_REPLY_UNAVAILABLE','reply cannot cross rooms');
select throws_ok($$select public.mark_business_chat_read('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001','b1960000-0000-4000-8000-000000000003')$$,'P0001','MESSAGE_NOT_VISIBLE','read cursor cannot point into another room');
select throws_ok($$select public.edit_business_chat_message('b1960000-0000-4000-8000-000000000002','b1910000-0000-4000-8000-000000000001','Peer edit')$$,'P0001','MESSAGE_OWNER_REQUIRED','business cannot edit personal peer message');
select lives_ok($$select public.mark_business_chat_read('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001','b1960000-0000-4000-8000-000000000002')$$,'shared read cursor advances');
select lives_ok($$select public.mark_business_chat_read('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001','b1960000-0000-4000-8000-000000000001')$$,'older read acknowledgement is harmless');
reset role;
select is((select message_id from private.business_chat_reads where conversation_id='b1950000-0000-4000-8000-000000000001'),'b1960000-0000-4000-8000-000000000002'::uuid,'read position is monotonic by timestamp and UUID');
set local role authenticated;
select is(public.delete_business_chat_message('b1960000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')->>'kind','text','operator can delete owner business message to a safe tombstone');
select is(public.delete_business_chat_message('b1960000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')->>'sender_id','b1910000-0000-4000-8000-000000000001','repeat delete is safe and actor-free');
reset role;
select ok(exists(select 1 from private.message_history where message_id='b1960000-0000-4000-8000-000000000001' and original->>'body'='Evidence before deletion'),'deletion preserves original safety content');
update private.merchants set status='paused' where id='b1910000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','paused business loses reads');
reset role;
update private.merchants set status='trial',consent='revoked' where id='b1910000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','revoked business consent loses reads');
reset role;
update private.merchants set consent='granted',owner_verified_at=null where id='b1910000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','unverified owner cannot authorize operators');
reset role;
update private.merchants set owner_verified_at=now(),deleted_at=now() where id='b1910000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','deleted business loses reads');
reset role;
update private.merchants set deleted_at=null where id='b1910000-0000-4000-8000-000000000001';
update auth.users set raw_app_meta_data='{}' where id='b1900000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','disabled current owner invalidates operator access');
reset role;
update auth.users set raw_app_meta_data='{"merchant_enabled":true}' where id='b1900000-0000-4000-8000-000000000001';
update auth.users set raw_app_meta_data='{}' where id='b1900000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','disabled operator cannot reuse a connection');
reset role;
update auth.users set raw_app_meta_data='{"merchant_enabled":true}' where id='b1900000-0000-4000-8000-000000000002';
update public.profiles set ai_safety_consent_at=null where id='b1900000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','missing actor safety consent fails closed');
reset role;
update public.profiles set ai_safety_consent_at=now() where id='b1900000-0000-4000-8000-000000000002';
set local role authenticated;
select lives_ok($$select public.end_business_conversation('b1950000-0000-4000-8000-000000000002','b1910000-0000-4000-8000-000000000001')$$,'business may end its room');
select throws_ok($$select public.send_business_chat_message('b1950000-0000-4000-8000-000000000002','b1910000-0000-4000-8000-000000000001',gen_random_uuid(),p_body=>'After end')$$,'P0001','CONVERSATION_NOT_ACTIVE','ended room cannot silently reopen on send');
select lives_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000002','b1910000-0000-4000-8000-000000000001')$$,'ended room evidence remains available to current endpoints');
select lives_ok($$select public.block_business_conversation('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'business blocks a personal endpoint');
reset role;
select ok(exists(select 1 from private.business_chat_blocks where business_id='b1910000-0000-4000-8000-000000000001' and other_id='b1900000-0000-4000-8000-000000000003'),'business block is keyed to public identities');
select is((select count(*) from public.blocks where blocker_id='b1900000-0000-4000-8000-000000000002'),0::bigint,'business block never creates personal operator block');
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.start_business_conversation(null,'b1910000-0000-4000-8000-000000000001',null)$$,'P0001','CONVERSATION_ACCESS_DENIED','blocked endpoint cannot start a replacement room');
reset role;
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2","session_id":"b1990000-0000-4000-8000-000000000004","app_metadata":{"role":"admin"}}',true);
set local role authenticated;
select lives_ok($$select public.get_admin_conversation('b1950000-0000-4000-8000-000000000001',null,null,null)$$,'AAL2 admin can review unreported business conversation');
select throws_ok($$select public.get_business_chat_messages('b1950000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001')$$,'P0001','CONVERSATION_ACCESS_DENIED','admin cannot impersonate a business without a connection');
reset role;
select ok(exists(select 1 from public.admin_access_logs where actor_id='b1900000-0000-4000-8000-000000000004' and resource_id='b1950000-0000-4000-8000-000000000001'),'admin conversation read is attributable');
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1","session_id":"b1990000-0000-4000-8000-000000000004","app_metadata":{"role":"admin"}}',true);
set local role authenticated;
select throws_ok($$select public.get_admin_conversation('b1950000-0000-4000-8000-000000000001',null,null,null)$$,'P0001','ADMIN_REQUIRED','AAL1 never receives safety admin evidence');
reset role;
select * from finish();
rollback;
